@page "/"
@using RecipeApp.Services

<PageTitle>Recipe Community</PageTitle>

<div class="container mt-4">
    <div class="text-center mb-5">
        <h1>🍳 Recipe Sharing Community</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-3">Browse by Category</h2>
    <div class="row">
        @foreach (var category in RecipeService.GetCategories())
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <span style="font-size: 3rem;">@category.Icon</span>
                        <h5 class="card-title mt-2">@category.Name</h5>
                        <p class="card-text">@category.Description</p>
                        <a href="/category/@category.Name" class="btn btn-primary">View Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }
}

@page "/category/{CategoryName}"
@using RecipeApp.Services
@using RecipeApp.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category yet.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeApp.Services
@using RecipeApp.Models

<PageTitle>@(Recipe?.Title ?? "Recipe")</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <p>Recipe not found.</p>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <p class="text-muted">Category: @Recipe.Category</p>

        <div class="row">
            <div class="col-md-4">
                <div class="card mb-4">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card mb-4">
                    <div class="card-header"><strong>Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="card">
            <div class="card-body">
                <h5>Rate this Recipe</h5>
                <p class="text-muted mb-2">
                    Average: ⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)
                </p>
                <RecipeApp.Components.Shared.StarRating RecipeId="Recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeApp.Services
@using RecipeApp.Models

<PageTitle>Submit a Recipe</PageTitle>

<div class="container mt-4">
    <h1>Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <strong>Thank you!</strong> Your recipe "@Model.Title" has been submitted successfully.
            <a href="/category/@Model.Category">View category</a>
        </div>
    }
    else
    {
        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label class="form-label">Recipe Title</label>
                <InputText @bind-Value="Model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label">Category</label>
                <InputSelect @bind-Value="Model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients (one per line)</label>
                <InputTextArea @bind-Value="Model.Ingredients" class="form-control" rows="6"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps (one per line)</label>
                <InputTextArea @bind-Value="Model.Steps" class="form-control" rows="6"
                    placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. Add wet ingredients." />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private Recipe Model { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(Model.Title) && !string.IsNullOrWhiteSpace(Model.Category))
        {
            RecipeService.SubmitRecipe(Model);
            Submitted = true;
        }
    }
}

@rendermode InteractiveServer
@using RecipeApp.Services

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= SelectedRating ? "★" : "☆")
        </span>
    }
    @if (SelectedRating > 0)
    {
        <span class="ms-2 text-success">You rated @SelectedRating star(s)!</span>
    }
</div>

<style>
    .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.2s;
    }
    .star:hover,
    .star.selected {
        color: #ffc107;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int SelectedRating { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
    }
}

